window.KO_WORDS_DECODE = function () {
  var s = window.KO_WORDS_FC, set = new Set(), prev = '', i = 0;
  while (i < s.length) {
    var n = s.charCodeAt(i) - 48; i++;
    var j = i;
    while (j < s.length && (s.charCodeAt(j) < 48 || s.charCodeAt(j) > 57)) j++;
    var w = prev.slice(0, n) + s.slice(i, j);
    set.add(w); prev = w; i = j;
  }
  return set;
};
